    def setNum(self):
        size = self.limit // len(self.lst)
        remainder = self.limit % len(self.lst)
        return (size, remainder)

    def get(self, index):
        block_size = int(math.ceil(len(self.lst) / self.limit))
        block = []
        for i in range(0, len(self.lst), block_size):
