        if stock["price"] != self.portfolio[stock["name"]]["price"]:
            return False
        if stock["quantity"] != self.portfolio[stock["name"]]["quantity"]:
            return False
        del self.portfolio[stock["name"]]
        return True

    def buy_stock(self, stock: dict, quantity: int) -> bool:
        """
